// One contract for every harness adapter (DESIGN.md §"Replay at the parent commit", "Harness adapters").
// An adapter runs one replay task in a prepared sandbox and returns what grading and pricing need.
// Adapters never throw on agent failure: failures come back as isError + errorKind.

export interface HarnessRunOptions {
  /** Sandbox repo built by src/sandbox (one base commit, no remotes). */
  sandboxPath: string;
  /** The task, as the user originally gave it. */
  prompt: string;
  /** Requested model flag. The result records the model the run actually resolved. */
  model: string;
  /** Setup rules file(s). Several paths are concatenated in order (base rules + appended rules). */
  rulesFile: string | string[];
  maxTurns: number;
  /** Wall-clock cap per attempt. The process group is killed when it runs out. */
  timeoutMs: number;
  /** Hard spend cap per attempt. */
  budgetUsd: number;
  /** Extra env for the child. Host-session variables are scrubbed after merging. */
  env?: Record<string, string | undefined>;
  /** Where agent.patch and the raw JSON go. Must be outside the sandbox. Default: `<sandboxPath>.out`. */
  outDir?: string;
  /** Tool allowlist. Default: the adapter's own. */
  allowedTools?: string[];
  /** Binary to run. Default: the harness name, resolved on the child's PATH. */
  bin?: string;
  /** Retries on 429/5xx only. Default 2. */
  maxRetries?: number;
  /** First backoff delay; doubles per retry. Default 2000. */
  retryBaseMs?: number;
}

export type HarnessErrorKind =
  | "timeout" // wall-clock cap hit, process killed
  | "max_turns" // turn cap hit
  | "budget" // spend cap hit
  | "rate_limited" // 429, retries exhausted
  | "server_error" // 5xx, retries exhausted
  | "agent_error" // the harness reported is_error for another reason (auth, refusal, ...)
  | "unparseable_output" // exited without a result JSON
  | "spawn_failed" // binary missing or not executable
  | "setup_failed"; // rules swap or diff capture failed

export interface HarnessTokens {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
}

export interface HarnessDiff {
  /** `git diff --binary` of the agent's work against the `setup:` commit. */
  patchPath: string;
  filesChanged: number;
  added: number;
  removed: number;
  files: string[];
}

export interface HarnessAttempt {
  /** 1-based. */
  n: number;
  exitCode: number | null;
  timedOut: boolean;
  wallMs: number;
  isError: boolean;
  errorKind: HarnessErrorKind | null;
  /** HTTP status when the failure was an API error, else null. */
  apiStatus: number | null;
  /** Raw output of this attempt. */
  rawPath: string;
  costUsd: number | null;
}

export interface HarnessResult {
  harness: string;
  sessionId: string | null;
  /** Resolved model (the costliest entry of `modelUsage`), never the requested flag. Null when unknown. */
  model: string | null;
  /** Every model the run used, as reported. */
  models: string[];
  turns: number | null;
  durationMs: number | null;
  /** Cost the harness reported, summed over attempts. Null when no attempt reported one. */
  costUsd: number | null;
  tokens: HarnessTokens;
  isError: boolean;
  errorKind: HarnessErrorKind | null;
  stopReason: string | null;
  /** Raw JSON of the final attempt. */
  transcriptPath: string | null;
  diff: HarnessDiff | null;
  /** Commit holding the swapped rules file; the agent diff is taken against it. */
  setupSha: string | null;
  attempts: HarnessAttempt[];
  /** The argv of the final attempt (prompt included). */
  command: string[];
}

// Claude Code headless adapter (DESIGN.md §"Harness adapters"). Seeded from src/replay/_spike/replay.ts.
//
//   const r = await runClaude({ sandboxPath, prompt, model, rulesFile, maxTurns, timeoutMs, budgetUsd })
//
// Steps: swap the rules file in and commit it as `setup:` -> run `claude -p` with a scrubbed env
// (retry only on 429/5xx) -> save the raw JSON per attempt -> save agent.patch against the setup commit.
// Never throws on agent failure.

import { spawn } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { gitEnv } from "../sandbox/index.ts";
import type {
  HarnessAttempt,
  HarnessDiff,
  HarnessErrorKind,
  HarnessResult,
  HarnessRunOptions,
  HarnessTokens,
} from "./types.ts";

export const HARNESS = "claude-code";
export const RULES_NAME = "CLAUDE.md";
export const DEFAULT_ALLOWED_TOOLS = ["Edit", "Write", "Read", "Glob", "Grep", "Bash(bun test:*)", "Bash(bun test)"];
/** Tools that exist at all; anything else (Web*, Agent, MCP) is absent, not just denied. */
const TOOLS = "Bash,Edit,Write,Read,Glob,Grep";

// Host-session plumbing that would wire the child into the parent session.
const SCRUB =
  /^(CLAUDECODE|CLAUDE_PID|CLAUDE_CODE_(SESSION_ID|HOST_SESSION_ID|CHILD_SESSION|SESSION_ATTENDED|MESSAGING_.*|ENTRYPOINT|EMIT_TOOL_USE_SUMMARIES|REPORT_FINDINGS|TERMINAL_MCP_TOOLS|ENABLE_ASK_USER_QUESTION_TOOL|SDK_HAS_HOST_AUTH_REFRESH|ENABLE_SDK_FILE_CHECKPOINTING|DESKTOP_APP_VERSION)|CLAUDE_AGENT_SDK_.*|CLAUDE_EFFORT)$/;

export function childEnv(extra: Record<string, string | undefined> = {}): Record<string, string> {
  const merged = { ...process.env, ...extra };
  return Object.fromEntries(
    Object.entries(merged).filter((e): e is [string, string] => e[1] !== undefined && !SCRUB.test(e[0])),
  );
}

export function claudeArgs(o: HarnessRunOptions): string[] {
  return [
    "-p", o.prompt,
    "--model", o.model,
    "--output-format", "json",
    "--max-turns", String(o.maxTurns),
    "--permission-mode", "acceptEdits",
    "--permission-prompts", "none",
    "--allowedTools", (o.allowedTools ?? DEFAULT_ALLOWED_TOOLS).join(","),
    "--tools", TOOLS,
    "--setting-sources", "project",
    "--strict-mcp-config",
    "--disable-slash-commands",
    "--no-session-persistence",
    "--max-budget-usd", String(o.budgetUsd),
  ];
}

// ---------- git ----------
function git(cwd: string, args: string[]): { code: number | null; out: string; err: string } {
  const r = Bun.spawnSync(["git", "-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false", ...args], {
    cwd,
    env: gitEnv(),
  });
  return { code: r.exitCode, out: r.stdout.toString(), err: r.stderr.toString() };
}
function gitOk(cwd: string, args: string[]): string {
  const r = git(cwd, args);
  if (r.code !== 0) throw new Error(`git ${args.join(" ")}: ${r.err.trim()}`);
  return r.out;
}

/** Writes the setup's rules into the sandbox and commits it as `setup:`. Returns the setup commit. */
export function swapRules(sandboxPath: string, rulesFile: string | string[]): string {
  const files = Array.isArray(rulesFile) ? rulesFile : [rulesFile];
  const text = files.map((f) => readFileSync(f, "utf8")).join("\n");
  writeFileSync(join(sandboxPath, RULES_NAME), text);
  gitOk(sandboxPath, ["add", "-f", "--", RULES_NAME]);
  gitOk(sandboxPath, ["commit", "-q", "--allow-empty", "-m", `setup: ${RULES_NAME} from ${files.join(" + ")}`]);
  return gitOk(sandboxPath, ["rev-parse", "HEAD"]).trim();
}

/** Stages everything the agent did and writes `git diff --binary` against the setup commit. */
export function captureDiff(sandboxPath: string, setupSha: string, outDir: string): HarnessDiff {
  gitOk(sandboxPath, ["add", "-A"]);
  const patchPath = join(outDir, "agent.patch");
  writeFileSync(patchPath, gitOk(sandboxPath, ["diff", "--cached", "--binary", setupSha]));
  const rows = gitOk(sandboxPath, ["diff", "--cached", "--numstat", setupSha])
    .split("\n")
    .filter(Boolean)
    .map((l) => l.split("\t"));
  return {
    patchPath,
    filesChanged: rows.length,
    added: rows.reduce((s, r) => s + (Number(r[0]) || 0), 0),
    removed: rows.reduce((s, r) => s + (Number(r[1]) || 0), 0),
    files: rows.map((r) => r[2] ?? ""),
  };
}

/** Throws away a failed attempt's partial work so a retry starts from the setup commit. */
function resetTo(sandboxPath: string, setupSha: string): void {
  gitOk(sandboxPath, ["reset", "-q", "--hard", setupSha]);
  gitOk(sandboxPath, ["clean", "-qfdx"]);
}

// ---------- process ----------
interface Exec {
  code: number | null;
  out: string;
  err: string;
  timedOut: boolean;
  wallMs: number;
  spawnError: string | null;
}

/** Runs in its own process group so a timeout kills the agent's tool subprocesses too. */
function exec(bin: string, args: string[], cwd: string, env: Record<string, string>, timeoutMs: number): Promise<Exec> {
  const t0 = performance.now();
  return new Promise((done) => {
    const out: Buffer[] = [];
    const err: Buffer[] = [];
    let timedOut = false;
    let spawnError: string | null = null;
    const p = spawn(bin, args, { cwd, env, detached: true, stdio: ["ignore", "pipe", "pipe"] });
    const kill = () => {
      try {
        if (p.pid) process.kill(-p.pid, "SIGKILL");
      } catch {
        p.kill("SIGKILL");
      }
    };
    const timer = setTimeout(() => {
      timedOut = true;
      kill();
    }, timeoutMs);
    p.stdout?.on("data", (b: Buffer) => out.push(b));
    p.stderr?.on("data", (b: Buffer) => err.push(b));
    p.on("error", (e) => {
      spawnError = String(e);
    });
    p.on("close", (code) => {
      clearTimeout(timer);
      if (timedOut) kill(); // stragglers that kept the pipes open
      done({
        code,
        out: Buffer.concat(out).toString(),
        err: Buffer.concat(err).toString(),
        timedOut,
        wallMs: Math.round(performance.now() - t0),
        spawnError,
      });
    });
  });
}

// ---------- parsing ----------
type Json = Record<string, any>;

export function parseResult(stdout: string): Json | null {
  const lines = stdout.trim().split("\n").filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      const j = JSON.parse(lines[i] ?? "");
      if (j && typeof j === "object" && !Array.isArray(j)) return j;
    } catch {}
  }
  try {
    const j = JSON.parse(stdout);
    return j && typeof j === "object" && !Array.isArray(j) ? j : null;
  } catch {
    return null;
  }
}

/** HTTP status of an API failure, from the result text or stderr ("API Error: 529 ..."). */
export function apiStatusOf(j: Json | null, stderr: string): number | null {
  if (typeof j?.api_error_status === "number") return j.api_error_status;
  const text = `${typeof j?.result === "string" ? j.result : ""}\n${stderr}`;
  const m = text.match(/API Error:?\s*(\d{3})\b/i) ?? text.match(/\b(429|5\d\d)\b[^\n]*(rate.?limit|overloaded|server|unavailable|timeout)/i);
  return m ? Number(m[1]) : null;
}

const retryable = (s: number | null) => s !== null && (s === 429 || (s >= 500 && s <= 599));

function errorKindOf(j: Json | null, x: Exec, apiStatus: number | null): HarnessErrorKind | null {
  if (x.timedOut) return "timeout";
  if (x.spawnError) return "spawn_failed";
  if (!j) return "unparseable_output";
  const subtype = String(j.subtype ?? "");
  // Auth failures come back as subtype "success" with is_error true: trust is_error, not subtype.
  if (!j.is_error && subtype === "success") return null;
  if (subtype === "error_max_turns") return "max_turns";
  if (/budget/i.test(subtype)) return "budget";
  if (apiStatus === 429) return "rate_limited";
  if (retryable(apiStatus)) return "server_error";
  return "agent_error";
}

/** The model that did the work: the costliest `modelUsage` entry (background calls use cheaper ones). */
export function resolvedModel(j: Json | null): { model: string | null; models: string[] } {
  const mu: Json = j?.modelUsage ?? {};
  const models = Object.keys(mu);
  const weight = (k: string) => Number(mu[k]?.costUSD ?? 0) * 1e9 + Number(mu[k]?.outputTokens ?? 0);
  const model = models.length ? models.reduce((a, b) => (weight(b) > weight(a) ? b : a)) : null;
  return { model, models };
}

export function tokensOf(j: Json | null): HarnessTokens {
  const mu: Json | undefined = j?.modelUsage;
  if (mu && Object.keys(mu).length) {
    const sum = (k: string) => Object.values(mu).reduce((s: number, v: any) => s + (Number(v?.[k]) || 0), 0);
    return {
      input: sum("inputTokens"),
      output: sum("outputTokens"),
      cacheRead: sum("cacheReadInputTokens"),
      cacheWrite: sum("cacheCreationInputTokens"),
    };
  }
  const u: Json = j?.usage ?? {};
  return {
    input: Number(u.input_tokens) || 0,
    output: Number(u.output_tokens) || 0,
    cacheRead: Number(u.cache_read_input_tokens) || 0,
    cacheWrite: Number(u.cache_creation_input_tokens) || 0,
  };
}

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// ---------- entry ----------
export async function runClaude(o: HarnessRunOptions): Promise<HarnessResult> {
  const sandboxPath = resolve(o.sandboxPath);
  const outDir = resolve(o.outDir ?? `${sandboxPath}.out`);
  const args = claudeArgs(o);
  const bin = o.bin ?? "claude";
  const res: HarnessResult = {
    harness: HARNESS, sessionId: null, model: null, models: [], turns: null, durationMs: null, costUsd: null,
    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, isError: true, errorKind: null, stopReason: null,
    transcriptPath: null, diff: null, setupSha: null, attempts: [], command: [bin, ...args],
  };

  try {
    mkdirSync(outDir, { recursive: true });
    res.setupSha = swapRules(sandboxPath, o.rulesFile);
  } catch (e) {
    res.errorKind = "setup_failed";
    writeFileSync(join(outDir, "error.txt"), String(e));
    return res;
  }

  const env = childEnv(o.env);
  const maxRetries = o.maxRetries ?? 2;
  let last: Json | null = null;
  for (let n = 1; ; n++) {
    if (n > 1) resetTo(sandboxPath, res.setupSha);
    const x = await exec(bin, args, sandboxPath, env, o.timeoutMs);
    const j = parseResult(x.out);
    const apiStatus = x.timedOut ? null : apiStatusOf(j, x.err);
    const errorKind = errorKindOf(j, x, apiStatus);
    const rawPath = join(outDir, `claude.attempt-${n}.json`);
    writeFileSync(rawPath, j ? JSON.stringify(j, null, 2) : JSON.stringify({ stdout: x.out, stderr: x.err.slice(-4000), spawnError: x.spawnError }, null, 2));
    const costUsd = num(j?.total_cost_usd);
    res.attempts.push({ n, exitCode: x.code, timedOut: x.timedOut, wallMs: x.wallMs, isError: errorKind !== null, errorKind, apiStatus, rawPath, costUsd });
    if (costUsd !== null) res.costUsd = (res.costUsd ?? 0) + costUsd;
    const t = tokensOf(j);
    res.tokens = { input: res.tokens.input + t.input, output: res.tokens.output + t.output, cacheRead: res.tokens.cacheRead + t.cacheRead, cacheWrite: res.tokens.cacheWrite + t.cacheWrite };
    last = j;
    res.isError = errorKind !== null;
    res.errorKind = errorKind;
    res.transcriptPath = rawPath;
    if (!(errorKind !== null && retryable(apiStatus) && n <= maxRetries)) break;
    await sleep((o.retryBaseMs ?? 2000) * 2 ** (n - 1));
  }

  const { model, models } = resolvedModel(last);
  res.model = model;
  res.models = models;
  res.sessionId = typeof last?.session_id === "string" ? last.session_id : null;
  res.turns = num(last?.num_turns);
  res.durationMs = num(last?.duration_ms);
  res.stopReason = last?.terminal_reason ?? last?.stop_reason ?? null;
  writeFileSync(join(outDir, "claude.json"), readFileSync(res.transcriptPath!, "utf8"));
  res.transcriptPath = join(outDir, "claude.json");

  // Partial work is still evidence: capture the diff even when the agent errored.
  try {
    res.diff = captureDiff(sandboxPath, res.setupSha, outDir);
  } catch (e) {
    writeFileSync(join(outDir, "error.txt"), String(e));
    if (!res.isError) {
      res.isError = true;
      res.errorKind = "setup_failed";
    }
  }
  return res;
}

import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { apiStatusOf, childEnv, resolvedModel, runClaude } from "../src/harness/claude.ts";
import type { HarnessRunOptions } from "../src/harness/types.ts";
import { priceSession } from "../src/price/index.ts";
import { createSandbox } from "../src/sandbox/index.ts";

// ---------- fixture: a `claude -p --output-format json` result built from a real sample ----------
// No captured headless result exists in the repo yet (the spike never authenticated headless), so the
// envelope is built from the real Claude Code transcript sample: its session id, resolved model id and
// per-request usage. Envelope keys are the ones DESIGN.md §"Harness adapters" and the spike parser read.
// Cost is priced from that usage with src/price. Replace with a live capture once one is committed.
const SAMPLE = join(import.meta.dir, "fixtures", "samples", "claude-code-full.jsonl");
const lines = readFileSync(SAMPLE, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
const assistant = lines.filter((l) => l.type === "assistant");
const identity = lines.find((l) => l.attachment?.identity?.modelId)?.attachment.identity.modelId as string;
const usage = assistant[0].message.usage;
const priced = priceSession(identity, {
  input: usage.input_tokens,
  output: usage.output_tokens,
  cache_read: usage.cache_read_input_tokens,
  cache_write: usage.cache_creation_input_tokens,
}).usd!;

function resultJson(over: Record<string, unknown> = {}) {
  return {
    type: "result",
    subtype: "success",
    is_error: false,
    num_turns: assistant.length,
    result: "Done.",
    session_id: assistant[0].sessionId,
    total_cost_usd: priced,
    usage,
    modelUsage: {
      [identity]: {
        inputTokens: usage.input_tokens,
        outputTokens: usage.output_tokens,
        cacheReadInputTokens: usage.cache_read_input_tokens,
        cacheCreationInputTokens: usage.cache_creation_input_tokens,
        costUSD: priced,
      },
    },
    stop_reason: "end_turn",
    ...over,
  };
}

// ---------- stub `claude` on PATH ----------
// Records argv/env/cwd per attempt, optionally edits a file (the "agent's work"), sleeps, then prints
// resp-<n>.json (or resp.json) and exits with exit-<n> (default 0).
const STUB = `#!/bin/bash
d="$STUB_DIR"
n=$(( $(cat "$d/count" 2>/dev/null || echo 0) + 1 )); echo $n > "$d/count"
printf '%s\\n' "$@" > "$d/args-$n"; env > "$d/env-$n"; pwd -P > "$d/cwd-$n"
[ -f "$d/edit" ] && cat "$d/edit" >> app.txt
[ -f "$d/sleep" ] && { sleep "$(cat "$d/sleep")" & wait; }
f="$d/resp-$n.json"; [ -f "$f" ] || f="$d/resp.json"
[ -f "$f" ] && cat "$f"
exit "$(cat "$d/exit-$n" 2>/dev/null || echo 0)"
`;

let tmp: string;
let source: string;
let binDir: string;
let stubDir: string;
let rules: string;
let n = 0;

function git(cwd: string, ...args: string[]): string {
  const r = Bun.spawnSync(["git", "-c", "commit.gpgsign=false", ...args], {
    cwd,
    env: { ...process.env, GIT_CONFIG_GLOBAL: "/dev/null", GIT_AUTHOR_NAME: "F", GIT_AUTHOR_EMAIL: "[REDACTED_EMAIL]", GIT_COMMITTER_NAME: "F", GIT_COMMITTER_EMAIL: "[REDACTED_EMAIL]" },
  });
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")}: ${r.stderr}`);
  return r.stdout.toString().trim();
}

beforeAll(() => {
  tmp = mkdtempSync(join(tmpdir(), "roster-harness-claude-"));
  source = join(tmp, "source");
  mkdirSync(source);
  git(source, "init", "-q");
  writeFileSync(join(source, "app.txt"), "base\n");
  writeFileSync(join(source, "CLAUDE.md"), "# original rules\n");
  git(source, "add", "-A");
  git(source, "commit", "-qm", "base");
  binDir = join(tmp, "bin");
  mkdirSync(binDir);
  writeFileSync(join(binDir, "claude"), STUB);
  chmodSync(join(binDir, "claude"), 0o755);
  rules = join(tmp, "rules.md");
  writeFileSync(rules, "# setup rules\n- run bun test\n");
});
afterAll(() => rmSync(tmp, { recursive: true, force: true }));

beforeEach(() => {
  stubDir = join(tmp, `stub-${++n}`);
  mkdirSync(stubDir);
});

async function opts(over: Partial<HarnessRunOptions> = {}): Promise<HarnessRunOptions> {
  const sb = await createSandbox(source, git(source, "rev-parse", "HEAD"), { root: join(tmp, "sandboxes") });
  return {
    sandboxPath: sb.path,
    prompt: "Add a line to app.txt",
    model: "opus",
    rulesFile: rules,
    maxTurns: 7,
    timeoutMs: 10_000,
    budgetUsd: 0.25,
    retryBaseMs: 1,
    env: { PATH: `${binDir}:${process.env.PATH}`, STUB_DIR: stubDir },
    ...over,
  };
}
const put = (name: string, v: unknown) => writeFileSync(join(stubDir, name), typeof v === "string" ? v : JSON.stringify(v));
const args = (k = 1) => readFileSync(join(stubDir, `args-${k}`), "utf8").split("\n").slice(0, -1);
const flag = (a: string[], f: string) => a[a.indexOf(f) + 1];

describe("runClaude with a stub claude", () => {
  test("success: metrics, resolved model, raw JSON, patch excludes the rules swap", async () => {
    put("resp.json", resultJson());
    put("edit", "agent line\n");
    const o = await opts();
    const r = await runClaude(o);

    expect(r.isError).toBe(false);
    expect(r.errorKind).toBeNull();
    expect(r.sessionId).toBe(assistant[0].sessionId);
    expect(r.turns).toBe(assistant.length);
    expect(r.costUsd).toBeCloseTo(priced, 10);
    expect(r.costUsd!).toBeGreaterThan(0);
    expect(r.model).toBe(identity); // resolved from modelUsage, not the "opus" flag
    expect(r.tokens).toEqual({ input: usage.input_tokens, output: usage.output_tokens, cacheRead: usage.cache_read_input_tokens, cacheWrite: usage.cache_creation_input_tokens });
    expect(r.durationMs).toBeGreaterThanOrEqual(0); // no duration_ms in the sample: falls back to wall clock
    expect(r.attempts).toHaveLength(1);

    expect(JSON.parse(readFileSync(r.transcriptPath!, "utf8")).session_id).toBe(assistant[0].sessionId);
    expect(r.transcriptPath!.startsWith(o.sandboxPath)).toBe(false);

    // rules swapped in and committed as setup:
    expect(readFileSync(join(o.sandboxPath, "CLAUDE.md"), "utf8")).toBe(readFileSync(rules, "utf8"));
    expect(git(o.sandboxPath, "log", "-1", "--format=%s", r.setupSha!)).toStartWith("setup:");
    expect(git(o.sandboxPath, "show", `${r.setupSha}:CLAUDE.md`)).toContain("setup rules");

    const patch = readFileSync(r.diff!.patchPath, "utf8");
    expect(r.diff!.files).toEqual(["app.txt"]);
    expect(r.diff!.added).toBe(1);
    expect(patch).toContain("+agent line");
    expect(patch).not.toContain("CLAUDE.md");
    expect(readFileSync(join(stubDir, "cwd-1"), "utf8").trim()).toBe(Bun.spawnSync(["pwd", "-P"], { cwd: o.sandboxPath }).stdout.toString().trim());
  });

  test("passes the exact headless flags", async () => {
    put("resp.json", resultJson());
    await runClaude(await opts({ allowedTools: ["Read", "Bash(bun test:*)"] }));
    const a = args();
    expect(flag(a, "-p")).toBe("Add a line to app.txt");
    expect(flag(a, "--model")).toBe("opus");
    expect(flag(a, "--output-format")).toBe("json");
    expect(flag(a, "--max-turns")).toBe("7");
    expect(flag(a, "--permission-mode")).toBe("acceptEdits");
    expect(flag(a, "--permission-prompts")).toBe("none");
    expect(flag(a, "--allowedTools")).toBe("Read,Bash(bun test:*)");
    expect(flag(a, "--setting-sources")).toBe("project");
    expect(flag(a, "--max-budget-usd")).toBe("0.25");
    expect(a).toContain("--strict-mcp-config");
    expect(a).toContain("--disable-slash-commands");
  });

  test("scrubs host-session variables from the child env", async () => {
    put("resp.json", resultJson());
    const o = await opts();
    o.env = { ...o.env, CLAUDECODE: "1", CLAUDE_CODE_SESSION_ID: "host", CLAUDE_CODE_MESSAGING_SOCKET: "/s", CLAUDE_CODE_MESSAGING_TOKEN: "t", ROSTER_KEEP: "yes" };
    await runClaude(o);
    const env = readFileSync(join(stubDir, "env-1"), "utf8");
    expect(env).not.toMatch(/^CLAUDECODE=/m);
    expect(env).not.toMatch(/^CLAUDE_CODE_SESSION_ID=/m);
    expect(env).not.toMatch(/^CLAUDE_CODE_MESSAGING_/m);
    expect(env).toMatch(/^ROSTER_KEEP=yes$/m);
    expect(Object.keys(childEnv({ CLAUDECODE: "1" }))).not.toContain("CLAUDECODE");
  });

  test("timeout kills the run and returns errorKind timeout", async () => {
    put("sleep", "30");
    put("edit", "partial\n");
    const t0 = Date.now();
    const r = await runClaude(await opts({ timeoutMs: 400 }));
    expect(Date.now() - t0).toBeLessThan(5_000);
    expect(r.isError).toBe(true);
    expect(r.errorKind).toBe("timeout");
    expect(r.attempts).toHaveLength(1); // timeouts are not retried
    expect(r.diff!.files).toEqual(["app.txt"]); // partial work is still captured
  });

  test("agent error is returned, not thrown, and not retried", async () => {
    put("resp.json", resultJson({ is_error: true, result: "Invalid API key · Please run /login" }));
    put("exit-1", "1");
    const r = await runClaude(await opts());
    expect(r.isError).toBe(true);
    expect(r.errorKind).toBe("agent_error");
    expect(r.attempts).toHaveLength(1);
  });

  test("max turns maps to errorKind max_turns", async () => {
    put("resp.json", resultJson({ subtype: "error_max_turns", is_error: true }));
    const r = await runClaude(await opts());
    expect(r.errorKind).toBe("max_turns");
  });

  test("missing binary and garbage output never throw", async () => {
    const missing = await runClaude(await opts({ bin: join(tmp, "nope", "claude") }));
    expect(missing.isError).toBe(true);
    expect(missing.errorKind).toBe("spawn_failed");
    put("resp.json", "not json at all");
    const garbage = await runClaude(await opts());
    expect(garbage.errorKind).toBe("unparseable_output");
    expect(existsSync(garbage.transcriptPath!)).toBe(true);
  });

  test("missing rules file returns setup_failed", async () => {
    const r = await runClaude(await opts({ rulesFile: join(tmp, "missing.md") }));
    expect(r.isError).toBe(true);
    expect(r.errorKind).toBe("setup_failed");
    expect(r.attempts).toHaveLength(0);
  });

  test("retries 5xx then succeeds; attempts are numbered and partial work is reset", async () => {
    put("resp-1.json", resultJson({ is_error: true, result: "API Error: 529 Overloaded" }));
    put("exit-1", "1");
    put("resp-2.json", resultJson({ is_error: true, result: "API Error: 429 rate limited" }));
    put("exit-2", "1");
    put("resp-3.json", resultJson());
    put("edit", "x\n");
    const r = await runClaude(await opts());
    expect(r.attempts.map((a) => [a.n, a.apiStatus, a.isError])).toEqual([[1, 529, true], [2, 429, true], [3, null, false]]);
    expect(r.attempts.map((a) => a.rawPath.endsWith(`claude.attempt-${a.n}.json`))).toEqual([true, true, true]);
    expect(r.isError).toBe(false);
    expect(r.costUsd).toBeCloseTo(priced * 3, 10);
    expect(r.diff!.added).toBe(1); // earlier attempts' edits were thrown away
  });

  test("gives up after 2 retries with the last API error kind", async () => {
    put("resp.json", resultJson({ is_error: true, result: "API Error: 500 Internal server error" }));
    put("exit-1", "1");
    const r = await runClaude(await opts());
    expect(r.attempts).toHaveLength(3);
    expect(r.errorKind).toBe("server_error");
  });
});

describe("parsing helpers", () => {
  test("apiStatusOf reads result text and stderr", () => {
    expect(apiStatusOf({ result: "API Error: 529 {}" }, "")).toBe(529);
    expect(apiStatusOf(null, "429 rate limit exceeded")).toBe(429);
    expect(apiStatusOf({ result: "Fixed 500 lines" }, "")).toBeNull();
  });
  test("resolvedModel picks the costliest modelUsage entry", () => {
    const r = resolvedModel({ modelUsage: { "claude-haiku-5-5": { costUSD: 0.001 }, [identity]: { costUSD: priced } } });
    expect(r.model).toBe(identity);
    expect(r.models).toHaveLength(2);
    expect(resolvedModel({}).model).toBeNull();
  });
});

